import { describe, it, expect } from "vitest";
import { createGeospatialCamera, setGeospatialOrientation } from "@babylonjs/lite";
import { tiltGlobeCamera } from "./globe-tilt.ts";

const R = 6371000;
function lookDotDown(cam: any, center: any) {
    // angle between look direction and direction to centre, and pitch via geocentric up
    const up = { x: center.x / Math.hypot(center.x, center.y, center.z), y: center.y / Math.hypot(center.x, center.y, center.z), z: center.z / Math.hypot(center.x, center.y, center.z) };
    const l = cam._lookAt;
    return -(l.x * up.x + l.y * up.y + l.z * up.z);
}

describe("tiltGlobeCamera", () => {
    for (const pitch of [0.1, 0.5, 1.2]) {
        it(`fresh camera tilt ${pitch}`, () => {
            const cam = createGeospatialCamera({ planetRadius: R });
            const before = { yaw: cam.yaw, radius: cam.radius, center: { ...cam.center } };
            expect(cam.radius).toBe(R * 4);
            tiltGlobeCamera(cam, pitch);
            expect(cam.pitch).toBeCloseTo(pitch, 9);
            expect(cam.radius).toBe(before.radius);
            expect(cam.yaw).toBeCloseTo(before.yaw, 9);
            expect(cam.center).toEqual(before.center);
            // camera actually looks at centre: position + look*radius == centre
            const c = cam.center;
            expect(cam.position.x + cam._lookAt.x * cam.radius).toBeCloseTo(c.x, -1);
            expect(cam.position.y + cam._lookAt.y * cam.radius).toBeCloseTo(c.y, -1);
            expect(cam.position.z + cam._lookAt.z * cam.radius).toBeCloseTo(c.z, -1);
            expect(lookDotDown(cam, c)).toBeCloseTo(Math.cos(pitch), 6);
            // survives zoom in/out
            for (const r of [R * 3, R * 1.5, R * 0.5, 50, R * 4]) {
                cam.radius = r;
                expect(cam.pitch).toBeCloseTo(pitch, 9);
                expect(lookDotDown(cam, c)).toBeCloseTo(Math.cos(pitch), 6);
            }
        });
    }
    it("non-trivial heading and centre preserved", () => {
        const cam = createGeospatialCamera({ planetRadius: R });
        setGeospatialOrientation(cam, { yaw: 1.0, radius: R * 2.5, center: { x: 0, y: R * 0.7, z: R * 0.7 } });
        const before = { yaw: cam.yaw, radius: cam.radius, center: { ...cam.center } };
        tiltGlobeCamera(cam, 0.8);
        expect(cam.pitch).toBeCloseTo(0.8, 9);
        expect(cam.yaw).toBeCloseTo(before.yaw, 9);
        expect(cam.radius).toBeCloseTo(before.radius, 3);
        expect(cam.center.x).toBeCloseTo(before.center.x, 3);
        expect(cam.center.y).toBeCloseTo(before.center.y, 3);
        expect(cam.center.z).toBeCloseTo(before.center.z, 3);
    });
});
EOF
